OUT = os.environ.get("E2E_OUT", "/tmp/little-engineer-e2e"); pathlib.Path(OUT).mkdir(parents=True, exist_ok=True); os.chdir(OUT)
from playwright.sync_api import sync_playwright
res = []
def ck(n, ok, info=""):
    res.append(bool(ok)); print(("PASS" if ok else "FAIL"), n, info)
def get(path):
    r = urllib.request.urlopen(BASE + path, timeout=15); return r.status, r.headers.get("content-type", ""), r.read()
st, ct, html = get("/"); html = html.decode()
ck("homepage 200", st == 200)
ck("title has the full name", re.search(r"<title>Milan Singla — ", html) is not None)
ck("meta description present", 'name="description"' in html and "Milan Singla" in html)
m = re.search(r'<script type="application/ld\+json">(.*?)</script>', html, re.S)
ld = json.loads(m.group(1)) if m else {"@graph": [{}, {}]}
ck("one JSON-LD block, parses, Person + WebSite", m is not None and [x.get("@type") for x in ld["@graph"]] == ["Person", "WebSite"])
ck("JSON-LD carries the site URL as a stable id", ld["@graph"][0].get("@id") == "https://milansingla.tech/#person" and ld["@graph"][1].get("url") == "https://milansingla.tech/")
ck("JSON-LD uses the real LinkedIn + GitHub URLs only", ld["@graph"][0].get("sameAs") == ["https://www.linkedin.com/in/milan-singla-146437215/", "https://github.com/milansingla"])
ck("no localhost / tunnel address in the head metadata", not re.search(r"localhost|trycloudflare|127\.0\.0\.1", html.split("</head>")[0]) and "localhost" not in (m.group(1) if m else ""))
ck("canonical and og:url point at https://milansingla.tech", re.search(r'rel="canonical" href="https://milansingla\.tech/?"', html) is not None and re.search(r'property="og:url" content="https://milansingla\.tech/?"', html) is not None)
ck("og:image is an absolute milansingla.tech URL", 'content="https://milansingla.tech/og.png"' in html)
ck("not noindex", "noindex" not in html)
ck("no grades on the page (CGPA / percentages)", not re.search(r"CGPA|Percentage", html))
st, ct, body = get("/robots.txt"); t = body.decode()
ck("robots.txt allows the site, blocks nothing, names the sitemap", st == 200 and "Allow: /" in t and "Disallow" not in t and "Sitemap: https://milansingla.tech/sitemap.xml" in t, t.replace("\n", " | "))
st, ct, body = get("/sitemap.xml"); t = body.decode()
ck("sitemap.xml is valid XML: the homepage and /cv, nothing else", st == 200 and "xml" in ct and t.count("<loc>") == 2 and "<loc>https://milansingla.tech/</loc>" in t and "<loc>https://milansingla.tech/cv</loc>" in t)
xml.dom.minidom.parseString(t); ck("sitemap parses", True)
st, ct, ico = get("/favicon.ico"); n = struct.unpack("<H", ico[4:6])[0]; sizes = sorted((ico[6 + 16 * i] or 256) for i in range(n))
ck("favicon.ico holds 16, 32 and 48 px images", st == 200 and sizes == [16, 32, 48], str(sizes))
st, ct, svg = get("/icon.svg"); ck("icon.svg is served and is the M", st == 200 and b"M7.5 24V8.5" in svg)
st, ct, png = get("/apple-icon.png"); ck("apple touch icon is a 180px PNG", st == 200 and png[:4] == b"\x89PNG" and struct.unpack(">II", png[16:24]) == (180, 180))
ck("page links the icons; the old stickman icon is gone", 'rel="icon"' in html and "data:image/svg" not in html.split("</head>")[0])
st, ct, cv = get("/Milan-Singla-CV.pdf"); ck("CV is served as a PDF", st == 200 and "pdf" in ct and cv[:4] == b"%PDF")
txt = subprocess.run(["pdftotext", "-layout", "-", "-"], input=cv, capture_output=True).stdout.decode()
ck("public CV has no phone, roll number, CGPA or percentages", not re.search(r"\+91|\b\d{10}\b|Roll No|CGPA|Percentage|%", txt) and "Milan Singla" in txt)
st, ct, og = get("/og.png"); ck("og.png exists, 1200x630", st == 200 and struct.unpack(">II", og[16:24]) == (1200, 630))
with sync_playwright() as p:
    b = p.chromium.launch()
    def ctxp(**kw):
        c = b.new_context(**kw); pg = c.new_page(); errs = []; bad = []
        pg.on("console", lambda m: errs.append(m.text) if m.type == "error" else None); pg.on("pageerror", lambda e: errs.append(str(e)))
        pg.on("response", lambda r: bad.append(r.url) if r.status >= 400 else None)
        return c, pg, errs, bad
    c, pg, errs, bad = ctxp(viewport={"width": 1440, "height": 900})
    pg.goto(BASE + "/"); pg.wait_for_timeout(5500)
    ck("monogram replaces the corner name", pg.locator(".chrome .ms").count() == 1 and pg.locator(".chrome b").count() == 0)
    ck("accessible name and home href", pg.get_attribute(".ms", "aria-label") == "Milan Singla — Home" and pg.get_attribute(".ms", "href") == "/")
