    ck("finished mark is drawn after the reveal", pg.evaluate("[...document.querySelectorAll('.ms path')].every(p=>getComputedStyle(p).strokeDashoffset==='0px')"))
    bx = pg.evaluate("(()=>{const r=document.querySelector('.ms').getBoundingClientRect();return [r.width,r.height]})()")
    ck("compact, touch-sized", bx[1] >= 44 and bx[0] <= 80, str(bx))
    pg.hover(".ms"); pg.wait_for_timeout(500)
    ck("hover: letters shift and the blue dot appears", pg.evaluate("getComputedStyle(document.querySelector('.ms-dot')).transform") != "none" and pg.evaluate("getComputedStyle(document.querySelector('.ms-m')).transform") != "none")
    pg.mouse.move(700, 600); pg.keyboard.press("Shift"); pg.focus(".ms")
    ck("focus ring is visible", pg.evaluate("document.activeElement.classList.contains('ms')") and pg.evaluate("getComputedStyle(document.querySelector('.ms')).outlineWidth") != "0px")
    lay0 = pg.evaluate("document.documentElement.scrollHeight")
    pg.click(".ms"); pg.wait_for_timeout(300)
    ck("click replays the reveal without navigating or shifting layout", pg.evaluate("document.querySelector('.ms').classList.contains('is-replay')") and pg.evaluate("location.pathname") == "/" and pg.evaluate("document.documentElement.scrollHeight") == lay0)
    ck("no console errors or failed requests", errs == [] and bad == [], str((errs[:2], bad[:2])))
    c.close()
    c, pg, errs, bad = ctxp(viewport={"width": 1440, "height": 900}, reduced_motion="reduce"); pg.goto(BASE + "/"); pg.wait_for_timeout(1500)
    ck("reduced motion: no monogram animation", pg.evaluate("[...document.querySelectorAll('.ms path')].every(p=>getComputedStyle(p).animationName==='none')"))
    c.close()
    c, pg, errs, bad = ctxp(viewport={"width": 1440, "height": 900}, java_script_enabled=False); pg.goto(BASE + "/"); pg.wait_for_timeout(600)
    ck("no JS: monogram is there and drawn", pg.locator(".ms").count() == 1 and pg.evaluate("getComputedStyle(document.querySelector('.ms-m')).strokeDashoffset") == "0px")
    c.close()
    for w, h in ((1280, 800), (768, 1024), (390, 844), (320, 640)):
        c, pg, errs, bad = ctxp(viewport={"width": w, "height": h}); pg.goto(BASE + "/?intro=skip"); pg.wait_for_timeout(1800)
        r = pg.evaluate("(()=>{const m=document.querySelector('.ms').getBoundingClientRect(),s=document.querySelector('.snd').getBoundingClientRect();return {vis:m.width>0&&m.left>=0&&m.top>=0,overlap:m.right>s.left&&m.left<s.right&&m.bottom>s.top&&m.top<s.bottom,ov:document.documentElement.scrollWidth>innerWidth}})()")
        ck(f"{w}px: monogram visible, clear of the sound control, no overflow", r["vis"] and not r["overlap"] and not r["ov"], str(r)); c.close()
    c, pg, errs, bad = ctxp(viewport={"width": 1440, "height": 900}); pg.goto(BASE + "/?intro=skip#contact"); pg.wait_for_timeout(2500)
    links = pg.evaluate("[...document.querySelectorAll('#contact .pg-links a')].filter(a=>/cv/i.test(a.getAttribute('href')||'')).map(a=>({h:a.getAttribute('href'),t:a.textContent.trim(),dl:a.hasAttribute('download')}))")
    ck("contact area: View CV goes to the branded /cv page, Download PDF is the file", len(links) == 2 and links[0] == {"h": "/cv", "t": "View CV", "dl": False} and links[1]["h"] == "/Milan-Singla-CV.pdf" and links[1]["dl"], str(links))
    with pg.expect_download() as dl:
        pg.evaluate("document.querySelector('#contact .pg-cv-dl').click()")
    ck("Download PDF downloads Milan-Singla-CV.pdf", dl.value.suggested_filename == "Milan-Singla-CV.pdf")
    c.close()
    c = b.new_context(viewport={"width": 1440, "height": 900}); pg = c.new_page(); pg.goto(BASE + "/?intro=skip")
    pg.evaluate("localStorage.setItem('le.sound.v1', JSON.stringify({fx:false,volume:0.4,music:true}))"); pg.reload(); pg.wait_for_timeout(2200)
    ck("remembered music shows as ready, not playing", pg.get_attribute(".snd-btn >> nth=1", "data-ready") == "true" and pg.get_attribute(".snd-btn >> nth=1", "aria-pressed") == "false" and "ready" in pg.get_attribute(".snd-btn >> nth=1", "title"))
    pg.click(".snd-btn >> nth=1"); pg.wait_for_timeout(400)
    ck("a click starts it and clears the ready mark", pg.get_attribute(".snd-btn >> nth=1", "aria-pressed") == "true" and pg.get_attribute(".snd-btn >> nth=1", "data-ready") is None)
    pg.click(".snd-btn >> nth=1"); pg.wait_for_timeout(300); pg.reload(); pg.wait_for_timeout(2000)
    ck("turned off by the visitor: not ready next time", pg.get_attribute(".snd-btn >> nth=1", "data-ready") is None)
    c.close()
    c, pg, errs, bad = ctxp(viewport={"width": 390, "height": 844}, is_mobile=True, has_touch=True); pg.goto(BASE + "/?intro=skip#part-02"); pg.wait_for_timeout(2500)
    xs = []; legs = set()
    for y in range(0, 3200, 160):
        pg.evaluate(f"window.scrollTo(0,{y})"); pg.wait_for_timeout(120)
        xs.append(pg.evaluate("(()=>{const r=document.querySelector('#part-02 .walker').getBoundingClientRect();return r.x+r.width*0.45})()"))
        legs.add(pg.evaluate("document.querySelector('#part-02 .walker [data-part=legL]').getAttribute('transform')"))
    ck("phone: the walker stays on the vertical road (x spread < 30px)", max(xs) - min(xs) < 30, f"{min(xs):.0f}..{max(xs):.0f}")
    ck("phone: never mirrored to face sideways", not pg.evaluate("document.querySelector('#part-02 .walker').classList.contains('is-flipped')"))
    ck("phone: he steps while scrolling (legs animate)", len(legs) > 1)
    by = set()
    for _ in range(10):
        pg.evaluate("window.scrollBy(0,40)"); pg.wait_for_timeout(70)
        by.add(pg.evaluate("document.querySelector('#part-02 .walker [data-part=body]').getAttribute('transform')"))
    ck("phone: the descend cycle bobs the body vertically", len(by) > 2, str(len(by)))
    pg.wait_for_timeout(1000); r1 = pg.evaluate("document.querySelector('#part-02 .walker [data-part=legL]').getAttribute('transform')"); pg.wait_for_timeout(500)
    ck("phone: legs settle when scrolling stops", pg.evaluate("document.querySelector('#part-02 .walker [data-part=legL]').getAttribute('transform')") == r1)
    ck("no console errors on mobile Part 02", errs == [], str(errs[:2]))
    # ───────── the branded CV page ─────────
    st, ct, cvhtml = get("/cv"); cvhtml = cvhtml.decode(); chead = cvhtml.split("</head>")[0]
    ck("/cv serves 200 HTML with its own title, canonical and og:url", st == 200 and "text/html" in ct and "<title>Milan Singla — CV (Curriculum Vitae)</title>" in chead and 'rel="canonical" href="https://milansingla.tech/cv"' in chead and 'property="og:url" content="https://milansingla.tech/cv"' in chead)
    ck("/cv is indexable, has no homepage JSON-LD, and one h1", "noindex" not in chead and cvhtml.count('<script type="application/ld+json"') == 0 and cvhtml.count("<h1") == 1)
    c, pg, errs, bad = ctxp(viewport={"width": 1440, "height": 900}); pg.goto(BASE + "/cv"); pg.wait_for_timeout(1500)
    ck("/cv: scrolling is not locked and there are no intro classes", pg.evaluate("(()=>{const h=document.documentElement;return !h.classList.contains('hero-open') && !h.classList.contains('intro') && getComputedStyle(h).overflow!=='hidden' && getComputedStyle(document.body).overflow!=='hidden'})()"))
    ck("/cv: monogram, heading, back link and download button present", pg.locator(".cv .ms").count() == 1 and pg.inner_text("h1").strip().upper() == "MILAN SINGLA" and pg.get_attribute(".cv-back", "href") == "/#contact" and pg.get_attribute(".cv-dl", "download") == "Milan-Singla-CV.pdf")
    ck("/cv desktop: the PDF is embedded in the page (not a redirect to the raw file)", pg.locator("object.cv-frame[type='application/pdf']").count() == 1 and pg.evaluate("location.pathname") == "/cv" and pg.evaluate("document.querySelector('object.cv-frame').data").endswith("/Milan-Singla-CV.pdf#view=FitH&toolbar=1"))
    r = pg.evaluate("(()=>{const f=document.querySelector('.cv-frame-wrap').getBoundingClientRect();return [f.height,innerHeight,document.documentElement.scrollWidth<=innerWidth]})()")
    ck("/cv desktop: viewer fits the viewport and nothing overflows", r[0] <= r[1] and r[2], str(r))
    with pg.expect_download() as dl:
        pg.evaluate("document.querySelector('.cv-dl').click()")
    ck("/cv: Download CV downloads the PDF", dl.value.suggested_filename == "Milan-Singla-CV.pdf")
    pg.click(".ms"); pg.wait_for_timeout(600)
    ck("/cv: the monogram is an ordinary link home", pg.evaluate("location.pathname") == "/")
    pg.goto(BASE + "/cv"); pg.wait_for_timeout(800); pg.click(".cv-back"); pg.wait_for_timeout(2500)
    ck("/cv: Back to portfolio returns to the contact section (no intro replay)", pg.evaluate("location.pathname+location.hash") == "/#contact" and pg.evaluate("document.documentElement.classList.contains('part2-open')"))
    ck("/cv: no console errors or failed requests", errs == [] and bad == [], str((errs[:2], bad[:2])))
    c.close()
    c, pg, errs, bad = ctxp(viewport={"width": 390, "height": 844}, is_mobile=True, has_touch=True); pg.goto(BASE + "/cv"); pg.wait_for_timeout(1500)
    r = pg.evaluate("(()=>{const i=document.querySelector('img.cv-img');return {img:!!i,ok:i&&i.complete&&i.naturalWidth>1000,w:i&&i.getBoundingClientRect().width,obj:document.querySelectorAll('object').length,ov:document.documentElement.scrollWidth>innerWidth}})()")
    ck("/cv phone: sharp one-page preview image, no embedded PDF, no overflow", r["img"] and r["ok"] and r["obj"] == 0 and not r["ov"] and r["w"] <= 390, str(r))
    ck("/cv phone: download still offered", pg.locator(".cv-dl").is_visible() and pg.locator(".cv-note a[download]").count() == 1)
    ck("/cv phone: no console errors", errs == [] and bad == [], str((errs[:2], bad[:2])))
    c.close()
