    for w, h in ((1280, 800), (768, 1024), (320, 640)):
        c, pg, errs, bad = ctxp(viewport={"width": w, "height": h}); pg.goto(BASE + "/cv"); pg.wait_for_timeout(1000)
        ck(f"/cv {w}px: no horizontal overflow", pg.evaluate("document.documentElement.scrollWidth<=innerWidth")); c.close()
    # ───────── the overlapping monogram ─────────
    c, pg, errs, bad = ctxp(viewport={"width": 1440, "height": 900}); pg.goto(BASE + "/?intro=skip"); pg.wait_for_timeout(1500)
    geo = pg.evaluate("(()=>{const m=document.querySelector('.ms-m').getBBox(),s=document.querySelector('.ms-s:not(.ms-halo)');const sb=s.getBoundingClientRect(),mb=document.querySelector('.ms-m').getBoundingClientRect();return {overlapX:Math.min(sb.right,mb.right)-Math.max(sb.left,mb.left),overlapY:Math.min(sb.bottom,mb.bottom)-Math.max(sb.top,mb.top),sw:sb.width,mw:mb.width}})()")
